{"implementation":"def solve(case):
    import math

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    for key in ("schema_version", "task_id", "registry_id", "nodes", "required_symbols", "_case_nonce"):
        if key not in case:
            raise ValueError("missing required case field: " + key)
    if case["schema_version"] != "effectslice-fg1-public-inputs.v1":
        raise ValueError("unsupported schema version")
    if case["task_id"] != "SE-PE-01":
        raise ValueError("unsupported task id")
    if not isinstance(case["registry_id"], str) or not isinstance(case["_case_nonce"], str):
        raise ValueError("invalid case metadata")
    if not isinstance(case["nodes"], list) or not isinstance(case["required_symbols"], list):
        raise ValueError("nodes and required_symbols must be arrays")
    if any(not isinstance(symbol, str) for symbol in case["required_symbols"]):
        raise ValueError("required symbols must be strings")

    nodes = case["nodes"]
    by_id = {}
    for node in nodes:
        if not isinstance(node, dict):
            raise ValueError("node must be an object")
        for key in ("id", "parent", "symbol", "depth", "removable", "utility"):
            if key not in node:
                raise ValueError("missing required node field: " + key)
        node_id = node["id"]
        if not isinstance(node_id, str) or node_id in by_id:
            raise ValueError("node ids must be unique strings")
        if node["parent"] is not None and not isinstance(node["parent"], str):
            raise ValueError("parent must be a string or null")
        if not isinstance(node["symbol"], str):
            raise ValueError("symbol must be a string")
        if isinstance(node["depth"], bool) or not isinstance(node["depth"], int) or node["depth"] < 0:
            raise ValueError("depth must be a nonnegative integer")
        if not isinstance(node["removable"], bool):
            raise ValueError("removable must be boolean")
        utility = node["utility"]
        if isinstance(utility, bool) or not isinstance(utility, (int, float)) or not math.isfinite(utility):
            raise ValueError("utility must be a finite number")
        by_id[node_id] = node

    roots = [node for node in nodes if node["parent"] is None]
    if len(roots) != 1 or roots[0]["depth"] != 0:
        raise ValueError("tree must have exactly one depth-zero root")
    root_id = roots[0]["id"]
    children = {node_id: [] for node_id in by_id}
    for node in nodes:
        parent = node["parent"]
        if parent is None:
            continue
        if parent not in by_id or parent == node["id"]:
            raise ValueError("invalid parent reference")
        if node["depth"] != by_id[parent]["depth"] + 1:
            raise ValueError("inconsistent node depth")
        children[parent].append(node["id"])

    for node_id in by_id:
        seen = set()
        current = node_id
        while current != root_id:
            if current in seen or current not in by_id:
                raise ValueError("tree contains a cycle or detached node")
            seen.add(current)
            parent = by_id[current]["parent"]
            if parent is None:
                raise ValueError("tree contains a detached root")
            current = parent

    required = set(case["required_symbols"])
    symbol_counts = {}
    for node in nodes:
        symbol_counts[node["symbol"]] = symbol_counts.get(node["symbol"], 0) + 1
    if any(symbol_counts.get(symbol, 0) == 0 for symbol in required):
        raise ValueError("required symbol is not represented")

    retained = set(by_id)
    removed = []
    candidates = sorted(nodes, key=lambda node: (-node["depth"], node["id"]))
    for node in candidates:
        node_id = node["id"]
        if node_id == root_id or not node["removable"] or node["symbol"] in required:
            continue
        if any(child_id in retained for child_id in children[node_id]):
            continue
        if symbol_counts[node["symbol"]] <= 0:
            raise ValueError("invalid symbol accounting")
        symbol_counts[node["symbol"]] -= 1
        if any(symbol_counts.get(symbol, 0) == 0 for symbol in required):
            symbol_counts[node["symbol"]] += 1
            continue
        retained.remove(node_id)
        removed.append(node_id)

    return {
        "removed_node_ids": removed,
        "retained_node_ids": sorted(retained),
    }
"}
